def main():
    notes={}
    for line in NOTES.strip().splitlines():
        label,proof,novelty,strength=line.split('|')
        notes[label]=(proof,novelty,strength)
    inventory=json.loads((ROOT/'tables/theorem_inventory.json').read_text())
    assert set(notes)=={r['label'] for r in inventory} and len(notes)==59
    rows=[]
    for i,r in enumerate(inventory,1):
        proof,novelty,strength=notes[r['label']]
        rows.append(dict(id=f'T{i:02d}',label=r['label'],title=r['title'],source=r['source'],line=r['line'],
                         correct_statement='No defect identified within the stated scope',
                         proof_complete='Supplied argument checked; no missing essential step identified',
                         proof_audit=proof,novelty=novelty,strength_and_issue=strength))
    dump(ROOT/'tables/theorem_audit.json',rows)
    with (ROOT/'tables/theorem_audit.csv').open('w',newline='') as f:
        w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
    out=['# Result-by-result theorem audit',
         'Audit date: 2026-09-13. The 45 distinct numbered theorem/proposition/lemma statements in the integrated manuscript and 14 numbered supplement results are audited below. Generated TeX copies of supplement statements are not counted twice. No separately stated corollaries occur in this active inventory.',
         '**Meaning of the judgment.** The statements and supplied proof arguments were read and reconstructed. “No defect identified” is a fallible review judgment, not a formal verification or a certificate of priority. The new finite checks can falsify selected steps but cannot prove a uniform theorem. Novelty judgments are relative to the focused closest-work review, not an exhaustive literature search.',
         'The machine-readable table has all requested columns (statement, proof completeness, novelty, strength and issue), plus source locations and proof reasoning. Detailed entries use a vertical layout for legibility.']
    for r in rows:
        rel='../'+r['source'].split('honest_tensor_functional_paper/',1)[1]
        out += [f"## {r['id']}. {r['title']}",f"**Result:** `{r['label']}`. **Location:** [{r['source'].split('honest_tensor_functional_paper/',1)[1]}]({rel}), line {r['line']}.",
                f"**Statement:** {r['correct_statement']}. **Proof completeness:** {r['proof_complete']}.",
                '**Proof audit:** '+r['proof_audit'],'**Novelty:** '+r['novelty'],'**Strength and issue:** '+r['strength_and_issue']]
    (ROOT/'theorem_audit.md').write_text('\n\n'.join(out)+'\n')
    print('Wrote',len(rows),'individual result audits.')

if __name__=='__main__':main()
